"""Perses-style syntax-guided reducer built over the simplified SparTree."""

from __future__ import annotations

import heapq
from typing import Iterable

from reduction.grammar import Grammar
from reduction.parser import Parser
from reduction.pnf import normalize_grammar
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import NodeType, SparTreeNode


Path = tuple[int, ...]


class PersesReducer(AbstractReducer):
    """Syntax-aware reducer combining tree ddmin and compatible replacement."""

    _QUANTIFIED_COLLECTIONS = {"program", "block", "elif_clauses", "except_clauses", "params"}

    def __init__(self, grammar: Grammar):
        self.grammar = normalize_grammar(grammar)
        self.parser = Parser(self.grammar)

    @property
    def name(self) -> str:
        return "perses"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        """Reduce ``tree`` while preserving the test property."""
        current = tree

        while True:
            queue = self._build_priority_queue(current)
            changed = False

            while queue:
                _, path = heapq.heappop(queue)
                node = self._get_node(current, path)
                if node is None or node.deleted or node.token_count() == 0:
                    continue

                if self._is_quantified_collection(node):
                    reduced = self._reduce_quantified_node(current, path, tester)
                    if reduced is not current:
                        current = reduced
                        changed = True
                        break

                if node.node_type == NodeType.REGULAR:
                    reduced = self._replace_with_compatible_descendant(current, path, tester)
                    if reduced is not current:
                        current = reduced
                        changed = True
                        break

            if not changed:
                return current

    def _build_priority_queue(self, root: SparTreeNode) -> list[tuple[int, Path]]:
        queue: list[tuple[int, Path]] = []
        for path, node in self._iter_nodes(root):
            if node.node_type == NodeType.TOKEN or node.deleted:
                continue
            heapq.heappush(queue, (-node.token_count(), path))
        return queue

    def _reduce_quantified_node(
        self,
        root: SparTreeNode,
        path: Path,
        tester: PropertyTester,
    ) -> SparTreeNode:
        working = root.clone()
        node = self._get_node(working, path)
        if node is None:
            return root

        active = [index for index, child in enumerate(node.children) if not child.deleted]
        min_keep = 1 if self._requires_non_empty(node) else 0
        if len(active) <= min_keep:
            return root

        changed = False
        granularity = 2

        while len(active) > min_keep and active:
            partitions = self._split(active, granularity)
            progress = False

            for partition in partitions:
                if len(active) - len(partition) < min_keep:
                    continue
                candidate = self._delete_children(working, path, partition)
                if tester.test(candidate.to_source()):
                    working = candidate
                    active = [index for index in active if index not in set(partition)]
                    granularity = max(granularity - 1, 2)
                    progress = True
                    changed = True
                    break

            if progress:
                continue

            for partition in partitions:
                if len(partition) < min_keep or len(partition) == len(active):
                    continue
                to_delete = [index for index in active if index not in set(partition)]
                candidate = self._delete_children(working, path, to_delete)
                if tester.test(candidate.to_source()):
                    working = candidate
                    active = list(partition)
                    granularity = 2
                    progress = True
                    changed = True
                    break

            if progress:
                continue

            if granularity >= len(active):
                break
            granularity = min(len(active), granularity * 2)

        if not changed:
            return root
        return self.parser.parse(working.to_source())

    def _replace_with_compatible_descendant(
        self,
        root: SparTreeNode,
        path: Path,
        tester: PropertyTester,
    ) -> SparTreeNode:
        node = self._get_node(root, path)
        if node is None or not path:
            return root

        candidates = [
            descendant
            for descendant_path, descendant in self._iter_nodes(node)
            if descendant_path
            and descendant.node_type != NodeType.TOKEN
            and descendant.rule_name == node.rule_name
            and descendant.token_count() < node.token_count()
            and self._node_indent(descendant) == self._node_indent(node)
        ]
        candidates.sort(key=lambda item: item.token_count())

        for candidate_subtree in candidates:
            candidate_tree = root.clone()
            replacement = candidate_subtree.clone()
            parent = self._get_node(candidate_tree, path[:-1])
            if parent is None:
                continue
            parent.children[path[-1]] = replacement
            source = candidate_tree.to_source()
            if tester.test(source):
                return self.parser.parse(source)

        return root

    def _is_quantified_collection(self, node: SparTreeNode) -> bool:
        if node.rule_name in self._QUANTIFIED_COLLECTIONS:
            return True
        rule = self.grammar.expected_rule(node.rule_name)
        if rule is None or not rule.is_quantified():
            return False
        if node.rule_name.endswith("_clause"):
            return False
        return all(child.node_type != NodeType.TOKEN for child in node.children)

    def _requires_non_empty(self, node: SparTreeNode) -> bool:
        rule = self.grammar.expected_rule(node.rule_name)
        return rule is not None and rule.rule_type == rule.rule_type.KLEENE_PLUS

    def _delete_children(self, root: SparTreeNode, path: Path, child_indexes: Iterable[int]) -> SparTreeNode:
        candidate = root.clone()
        node = self._get_node(candidate, path)
        if node is None:
            return candidate
        for index in child_indexes:
            if 0 <= index < len(node.children):
                node.children[index].delete()
        return candidate

    def _node_indent(self, node: SparTreeNode) -> int:
        tokens = node.tokens()
        if tokens and tokens[0].type == "INDENT":
            return len(tokens[0].value)
        return 0

    def _iter_nodes(self, root: SparTreeNode) -> list[tuple[Path, SparTreeNode]]:
        items: list[tuple[Path, SparTreeNode]] = []
        stack: list[tuple[Path, SparTreeNode]] = [((), root)]
        while stack:
            path, node = stack.pop()
            if node.deleted:
                continue
            items.append((path, node))
            for index in range(len(node.children) - 1, -1, -1):
                stack.append((path + (index,), node.children[index]))
        return items

    def _get_node(self, root: SparTreeNode, path: Path) -> SparTreeNode | None:
        node = root
        for index in path:
            if index >= len(node.children):
                return None
            node = node.children[index]
        return node

    def _split(self, values: list[int], n: int) -> list[list[int]]:
        if not values:
            return []
        if n > len(values):
            n = len(values)

        result: list[list[int]] = []
        base = len(values) // n
        remainder = len(values) % n
        start = 0

        for index in range(n):
            width = base + (1 if index < remainder else 0)
            result.append(values[start:start + width])
            start += width

        return [partition for partition in result if partition]

